    "pashtoSummary": "دا کیسه د دوو صمیمی ملګرو د دوستۍ او اتلولۍ ده چې په باکسنګ کې سره مخامخ کیږي او دا ثابتوي چې ورورولي او مینه له هرې بریا څخه لوړه ده.",
