    "type": "prose",
    "author": "KPK Textbook Board, Peshawar",
    "authorInfo": "An exploration of Islamic architectural brilliance in Moorish Spain and Allama Muhammad Iqbal's profound poetic pilgrimage to the Great Mosque of Cordoba in 1933.",
