    "pashtoTranslation": "دا لوست د اسلامي تمدن او د قرطبې تاریخي جومات عظمت او د علامه اقبال فلسفي افکار او شاهکار نظم بیانوي.",
    "englishTranslation": "This unit recounts the historical glory of Islamic civilization in Moorish Spain and Allama Muhammad Iqbal's 1933 visit to the Great Mosque of Cordoba. Mesmerized by the forest of marble pillars and horseshoe arches, Iqbal composed his immortal philosophical poem 'Masjid-e-Qurtaba', seeing the mosque as a monument of pure faith, passion ('Ishq'), and timeless creative vitality.",
