        "headingPashto": "برخه 2: د پاکستان په تحریک کې د ښځو رول",
        "text": "It was Quaid-e-Azam Muhammad Ali Jinnah who brought about a profound social revolution in the empowerment of Muslim women. Recognizing that no national liberation struggle could succeed while half the population remained marginalized, the Quaid tirelessly advocated for female emancipation. In a historic speech at Aligarh Muslim University in 1944, he declared with unshakeable conviction:\n\n'No nation can rise to the height of glory unless your women are side by side with you; we are victims of evil customs. It is a crime against humanity that our women are shut up within the four walls of the houses as prisoners.'\n\nUnder his inspiring leadership, the All-India Muslim League established a Central Women's Subcommittee in 1938, creating formal provincial branches to mobilize women across urban and rural India.",
