        "headingPashto": "برخه 3: د پاکستان په تحریک کې د ښځو رول",
        "text": "Foremost among the towering personalities was the Quaid's devoted sister, Mohtarma Fatima Jinnah—affectionately titled 'Madar-e-Millat' (Mother of the Nation). As his constant companion, confidante, and adviser, she traveled the length and breadth of British India, rallying Muslim women under the banner of the Muslim League.\n\nOther prominent leaders emerged across all regions: Begum Jahanara Shahnawaz, Begum Salma Tassaduq Hussain, and Begum Fatima from Lahore; Begum Shaista Ikramullah from Bengal; Miss Zari Sarfraz from Khyber Pakhtunkhwa; and Lady Abdullah Haroon from Sindh. As the Pakistan Movement gained momentum, the Muslim Students Federation and its vibrant women's wing played an increasingly decisive role in mass mobilization. Young female students traveled even to the remote districts of Khyber Pakhtunkhwa, defying deep-seated social conservatism to establish girl student committees. Begum Fatima, founder principal of the Jinnah Islamia College for Girls in Lahore, played a stellar role in training and inspiring female student cadres.",
