          "topic": "Prepositional Phrases (Exercise C)",
          "rule": "A Prepositional Phrase begins with a preposition and ends with a noun, pronoun, or noun phrase object (along with any modifiers). It functions as an adjective modifying a noun or as an adverb modifying a verb.",
