        "heading": "1. Water Resources and the Three River Basins of Pakistan",
        "headingUrdu": "حصہ 1: پاکستان میں پانی کی قلت کا بحران",
        "headingPashto": "برخه 1: په پاکستان کې د اوبو د کمښت بحران",
        "text": "Pakistan is a land gifted with lavish resources of water. It is a land where crystalline glacial water rolls down the mighty Himalayas, Karakoram, and Hindukush peaks to the fertile plains and breaks into an intricate web of canal systems that irrigates over 16 million hectares of land, out of 34 million hectares of cultivable land available. The other sources of water available in Pakistan are rainfall, surface water in rivers, and underground aquifers.\n\nIn surface water, Pakistan has three primary river drainage basins:\n1. The Indus River Basin: Considered the lifeblood of Pakistan. Its water sources are snowfall, glacier melt, and monsoon rainfall. From the Indus River system, approximately 141.67 million acre feet (MAF) of water is received annually. In 1960, Pakistan signed a historic water treaty with India called the 'Indus Waters Treaty'. This treaty gave the rights of three eastern rivers—Beas, Sutlej, and Ravi—to India, whereas the waters of the three western rivers—Indus, Jhelum, and Chenab—were allocated exclusively to Pakistan.\n2. The Closed Basin of the Kharan Desert: Consisting of mountain basins around Quetta and tributaries draining into the desert sinks, including the Pishin Lora and Bado rivers.\n3. The Makran Coastal Basin: Comprising short coastal streams in Balochistan and Sindh, including the Malir, Hub, Porali, Kud, Hingol, and Dasht rivers.",
        "paras": [
          "Pakistan is a land gifted with lavish resources of water. It is a land where crystalline glacial water rolls down the mighty Himalayas, Karakoram, and Hindukush peaks to the fertile plains and breaks into an intricate web of canal systems that irrigates over 16 million hectares of land, out of 34 million hectares of cultivable land available. The other sources of water available in Pakistan are rainfall, surface water in rivers, and underground aquifers.",
          "In surface water, Pakistan has three primary river drainage basins:",
          "1. The Indus River Basin: Considered the lifeblood of Pakistan. Its water sources are snowfall, glacier melt, and monsoon rainfall. From the Indus River system, approximately 141.67 million acre feet (MAF) of water is received annually. In 1960, Pakistan signed a historic water treaty with India called the 'Indus Waters Treaty'. This treaty gave the rights of three eastern rivers—Beas, Sutlej, and Ravi—to India, whereas the waters of the three western rivers—Indus, Jhelum, and Chenab—were allocated exclusively to Pakistan.",
          "2. The Closed Basin of the Kharan Desert: Consisting of mountain basins around Quetta and tributaries draining into the desert sinks, including the Pishin Lora and Bado rivers.",
          "3. The Makran Coastal Basin: Comprising short coastal streams in Balochistan and Sindh, including the Malir, Hub, Porali, Kud, Hingol, and Dasht rivers."
        ],
        "urdu": "پاکستان کے تین بڑے آبی طاس ہیں: دریائے سندھ کا طاس (جو ملک کی لائف لائن ہے)، خاران کا بند طاس، اور مکران کا ساحلی طاس۔",
        "pashto": "پښتو ترجمه او مفهوم: Water Resources and the Three River Basins of Pakistan"
