        "urdu": "ڈیموں کی کمی کے باعث ہر سال 70 ارب ڈالر کا قیمتی میٹھا پانی سمندر کی نذر ہو جاتا ہے جبکہ فی کس پانی کی دستیابی 5000 سے گر کر 1000 کیوبک میٹر رہ گئی ہے۔",
        "pashto": "پښتو ترجمه او مفهوم: The Staggering $70 Billion Economic Waste"
