    "pashtoTranslation": "دا ساینسي لوست د جینټیک انجینرۍ او بدلو شویو فصلونو ګټې او احتمالي خطرونه روښانه کوي.",
    "englishTranslation": "This informative science unit explores the development and controversy surrounding Genetically Modified Organisms (GMOs). By inserting beneficial genes from one organism into another, scientists produce drought-resistant, pest-tolerant crops like Bt cotton and golden rice, boosting food security. It also assesses legitimate ecological and health debates surrounding bioengineered crops.",
