          "rule": "Sentences are classified by function into four categories: Declarative (makes a statement, ends with period), Interrogative (asks a question, ends with question mark), Imperative (gives a command, request, or instruction), and Exclamatory (expresses strong emotion, ends with exclamation mark).",
