    "pashtoTranslation": "دا لوست د حضرت عمر فاروق رض بې ساري عدل، ساده ژوند، او د اسلامي فلاحي ریاست د تاریخي بنسټونو تفصیلي بیان کوي.",
    "englishTranslation": "This biographical chapter highlights the extraordinary life and governance of Hazrat Umar ibn al-Khattab (RA). As the Second Caliph, he expanded Islamic rule while instituting landmark administrative departments (Bait-ul-Mal, judiciary, police, postal system, revenue records). His personal austerity, accountability, and legendary justice established the foundational welfare state model in world history.",
