      "writingTasks": [
        {
          "summary": "This biographical chapter highlights the extraordinary life, exemplary governance, and moral integrity of Hazrat Umar Farooq (RA), the Second Caliph of Islam. Born in Makkah and embracing Islam at age 27, his conversion emboldened early Muslims to pray openly at the Ka'aba. During his decade-long caliphate, he established an empire spanning three continents, yet remained the ultimate model of simplicity, justice, and accountability. He regarded his authority over the public treasury (Bait-ul-Mal) merely as an orphan's trust, living on plain barley bread and wearing patched robes. He actively welcomed public criticism, stating that leaders who ignore the voices of their citizens are of no good. The lesson details his legendary night patrols, where he personally carried a heavy sack of flour on his own back to cook a meal for starving children whose mother was boiling stones in water. His honesty was absolute: he refused to take medicine honey from the state treasury without the public's consent, and deposited diplomatic jewels gifted to his wife into the public coffer. His sublime justice earned him the title 'Al-Farooq' and the highest prophetic praise.",
          "essay": {
            "title": "Hazrat Umar (RA): The Ruler as a Humble Public Servant",
            "text": "Throughout human history, political power has often corrupted leaders, transforming rulers into despots who exploit state wealth for personal vanity. In sharp contrast, Hazrat Umar Farooq (RA), the Second Caliph of Islam, established an administrative philosophy that redefined leadership as selfless servitude rather than sovereign privilege. By embodying the principle that a leader is the humble servant of his people, Hazrat Umar created the foundational blueprint for an incorruptible welfare state.\n\nHazrat Umar's governance was anchored in radical accountability and transparent stewardship. Although he commanded the mighty resources of an empire that eclipsed both the Roman and Persian domains, he refused all royal trappings. He dressed in garments bearing twelve patches, slept on plain palm-fiber mats under the open sky, and regarded the public treasury with the solemn reverence of a trustee guarding an orphan's inheritance. When citizens openly questioned his expenditures in public assemblies, he did not invoke royal immunity; rather, he celebrated their vigilance, asserting that a society lacking the courage to hold rulers accountable loses its moral purpose.\n\nHis compassion for the marginalized remains unmatched in the annals of governance. Rather than relying on sanitized intelligence reports, Hazrat Umar patrolled the dark streets of Madina himself to witness the hardships of ordinary citizens. His nocturnal journey to the tent of the impoverished widow—where he carried heavy grain sacks upon his own back, blew the hearth fires with his own breath, and fed weeping children—demonstrates that true greatness lies in personal empathy.\n\nIn conclusion, Hazrat Umar's legacy proves that righteous leadership is measured not by monuments or personal wealth, but by justice, humility, and the welfare of the poorest citizens. In an era troubled by political cynicism, his life remains an immortal beacon of ethical governance."
          },
          "translationUrdu": [
            {
              "english": "I have no more authority over the Bait-ul-Mal than a custodian has over the property of an orphan.",
              "urdu": "بیت المال پر میرا حق اس سے زیادہ نہیں ہے جتنا کسی یتیم کے مال پر اس کے نگران اور سرپرست کا ہوتا ہے۔"
            },
            {
              "english": "Brothers! I am your servant and you should neither unnecessarily hoard nor waste. I must work for the welfare and prosperity of our people.",
              "urdu": "اے بھائیو! میں آپ کا خادم ہوں اور آپ کو بلاوجہ مال نہ ذخیرہ کرنا چاہیے اور نہ ضائع کرنا چاہیے۔ مجھے اپنے عوام کی فلاح اور خوشحالی کے لیے کام کرنا ہے۔"
            },
            {
              "english": "If Allah had wished that there should have been another Nabi after me, he would have been Umar.",
              "urdu": "اگر اللہ تعالیٰ کا ارادہ ہوتا کہ میرے بعد کوئی اور نبی ہو، تو وہ عمر ہوتا۔"
            }
          ]
        }
      ],
