          "answer": "Oscar Wilde's delightfully witty short story revolves around Hughie Erskine, a charming, good-natured young man without a steady income. Visiting his artist friend Alan Trevor, Hughie takes pity on a ragged, miserable beggar modeling as a beggar-man and hands him his last sovereign. It turns out the beggar is Baron Hausberg, one of Europe's richest men. Touched by Hughie's genuine kindness, the Baron sends him a wedding present of 10,000 pounds, fulfilling the condition to marry his love Laura Merton.",
