    "pashtoTranslation": "دا الهام بښونکی شعر انسان ته دا امید ورکوي چې هر نوی سهار د نوي ژوند او بریا نوی فرصت دی، تېرې ناکامۍ شاته پریږدئ او بیا هڅه وکړئ.",
    "englishTranslation": "Walter Malone's uplifting poem 'Opportunity' challenges the ancient superstition that opportunity knocks but once. The poetic persona proclaims: 'They do me wrong who say I come no more; when once I knock and fail to find you in; for every day I stand outside your door, and bid you wake, and rise to fight and win.' It offers solace and renewed determination to anyone who has suffered past failure.",
