    "urduSummary": "والٹر میلون کی متاثر کن نظم 'اپرچونیٹی' اس غلط فہمی کی تردید کرتی ہے کہ موقع صرف ایک بار ملتا ہے۔ شاعر کہتا ہے کہ ہر نیا دن ایک نیا موقع لے کر آتا ہے۔ ماضی کے غموں اور ناکامیوں کو بھول کر جاگو، ہمت کرو اور دوبارہ جدوجہد کر کے فتح حاصل کرو۔",
    "pashtoSummary": "دا الهام بښونکی شعر انسان ته دا امید ورکوي چې هر نوی سهار د نوي ژوند او بریا نوی فرصت دی، تېرې ناکامۍ شاته پریږدئ او بیا هڅه وکړئ.",
